(window.TNQ=window.TNQ||[]).push({"terms":{"성숙":{"d":"경험이나 훈련과 관계없이 유전적으로 정해진 순서대로 진행되는 변화입니다.","r":[]},"집단무의식":{"d":"융이 말한 인류가 공유하는 무의식으로 원형이 구성요소입니다.","r":[]},"그림자":{"d":"융의 이론에서 인간이 자기 일부로 받아들이기 꺼리는 어두운 면입니다.","r":[]},"사회적 관심":{"d":"아들러가 말한 타인과 공동체에 대한 관심으로 인간을 움직이게 하는 동기입니다.","r":[]},"자아":{"d":"프로이트의 성격 구조에서 현실원칙에 따라 욕구와 현실을 조정하는 부분입니다.","r":[]},"실수행위":{"d":"말실수처럼 무의식이 드러나는 것으로 프로이트가 무의식의 증거로 본 행위입니다.","r":[]},"미시체계":{"d":"개인이 직접 경험하는 부모, 교사, 형제 같은 가까운 환경입니다.","r":[]},"대상영속성":{"d":"눈앞에서 사라진 물체도 계속 존재한다고 아는 인지 능력으로 영아기에 형성됩니다.","r":[]},"상상적 관중":{"d":"청소년이 남들이 자신을 항상 지켜본다고 믿는 사고입니다.","r":[]},"개성화":{"d":"융의 이론에서 중년기에 내면에 초점을 두고 참된 자기를 실현해 가는 과정입니다.","r":[]},"자아통합":{"d":"에릭슨이 노년기의 발달과제로 본 지나온 삶을 의미 있게 받아들이는 일입니다.","r":[]},"문화변용":{"d":"서로 다른 문화가 접촉하면서 한쪽이나 양쪽의 문화 양식이 변하는 현상입니다.","r":["문화마찰"]},"문화마찰":{"d":"서로 다른 문화가 만나 충돌하고 갈등을 빚는 현상입니다.","r":["문화변용"]},"문화적 역량":{"d":"다양한 문화적 배경의 클라이언트를 효과적으로 만날 수 있는 지식, 태도, 기술입니다.","r":[]}},"notes":{"2차적 사고과정과 현실원칙에 의해 지배된다":"자아는 2차적 사고과정을 쓰며 현실원칙에 따라 움직입니다.","46세 이후에 그릇된 가정을 모두 극복하고 진정한 자아를 찾는 시기라고 하였다":"굴드는 46세 이후를 그릇된 가정을 모두 벗고 참된 자아를 찾는 시기라고 했습니다.","“생산성 대 침체”라는 심리사회적 위기를 극복하게 되면 돌봄(care)의 덕목을 갖추게 된다":"에릭슨은 중년기의 생산성 대 침체라는 위기를 극복하면 돌봄의 덕목을 갖춘다고 했습니다.","각 체계들로부터 다양하고 객관적인 정보획득이 용이하다":"각 체계에서 다양하고 객관적인 정보를 쉽게 얻을 수 있습니다.","각 체계들로부터 다양한 정보획득이 용이하다":"생태체계관점은 여러 체계에서 정보를 얻기 쉽다는 장점이 있습니다.","강화계획 중에서 반응률이 가장 높다":"가변비율계획은 강화계획 중 행동이 나오는 비율이 가장 높습니다.","개인무의식과 집단무의식으로 나뉜다":"융은 무의식을 개인무의식과 집단무의식 두 가지로 나누었습니다.","개인의 성장 과정에서 나타나는 문제의 원인을 이해하는 데 도움을 제공한다":"성장 과정에서 나타나는 개인의 문제가 왜 생겼는지 이해하는 데 도움이 됩니다.","개인의 소득이 줄어들고, 상실을 경험하며 자아정체감이 저하되기도 한다":"은퇴로 소득이 줄고 상실감을 겪으며 자아정체감이 낮아지기도 합니다.","개인이 사회적 요구에 반응하기 위한 가면을 의미한다":"페르소나는 사회의 요구에 응하려고 개인이 쓰는 가면입니다.","개인적 욕구와 사회적 욕구 사이에 균형을 찾아 직업을 선택하는 시기이다":"청년기에는 개인적 욕구와 사회적 욕구의 균형을 찾아 직업을 고릅니다.","경험이나 훈련의 결과와 상관없이 진행된다":"성숙은 경험이나 훈련의 결과와 상관없이 유전적 계획에 따라 진행됩니다.","공동의 문제를 해결하고 삶의 질 향상을 위해 조직화가 가능한 대상이다":"지역사회는 공동의 문제를 풀고 삶의 질을 높이려고 조직화할 수 있는 대상입니다.","남자아이는 오이디푸스 콤플렉스(Oedipus complex)로 인한 거세불안을 경험한다":"남근기의 남자아이는 오이디푸스 콤플렉스 때문에 거세불안을 겪습니다.","노년기를 노인 개인과 사회가 동시에 상호분리를 시작하는 시기로 보는 이론이다":"분리이론은 노년기에 노인과 사회가 동시에 서로 멀어지기 시작한다고 봅니다.","노년기를 잘 보내기 위해서는 은퇴와 같은 종결되는 역할들을 대치할 수 있는 활동을 발견하는 것이 중요하다는 이론이다":"활동이론은 은퇴로 끝난 역할을 대신할 활동을 찾는 것이 노년기를 잘 보내는 길이라고 봅니다.","노년기의 발달과제로 자아통합이 중요하다고 주장하였다":"에릭슨은 노년기의 발달과제로 지나온 삶을 받아들이는 자아통합을 꼽았습니다.","다른 사람이 경험하는 위기가 자신에게는 일어나지 않으리라 믿는다":"청소년은 다른 사람에게 닥친 위기가 자기에게는 일어나지 않을 거라고 믿습니다.","다양한 문화나 언어를 공유하고 상호 존중하여 적극 수용하려는 입장을 취한다":"다문화주의는 다양한 문화와 언어를 서로 존중하고 적극 받아들이려는 입장입니다.","다양한 문화적 배경의 클라이언트를 대상으로 사회복지실천을 하기 위해서는 문화적 역량이 요구된다":"다양한 문화적 배경을 가진 클라이언트를 만나려면 문화적 역량이 필요합니다.","대상영속성(object permanence)이 형성된다":"영아기에는 눈앞에 없는 물체도 존재한다고 아는 대상영속성이 형성됩니다.","모든 사람을 자신의 관점에서만 본다":"유아기는 모든 사람을 자기 관점에서만 보는 자기중심적 사고를 합니다.","목적지향적이며 분업적 특성이 있다":"조직은 목적을 향해 움직이며 일을 나누어 하는 분업적 특성이 있습니다.","문제에 대한 총체적 이해와 접근을 용이하게 해준다":"생태체계관점은 문제를 전체적으로 이해하고 접근하기 쉽게 해 줍니다.","문제에 대한 총체적 이해와 조망을 제공한다":"생태체계관점은 문제를 총체적으로 이해하고 조망할 수 있게 합니다.","문화변용, 문화마찰 등의 용어는 문화의 역동적 특성을 나타낸다":"문화변용과 문화마찰은 문화가 계속 변하는 역동성을 보여 주는 말입니다.","미시체계 간의 상호작용에 초점을 둔다":"미시체계는 개인과 환경이 아니라 미시체계 사이의 상호작용에 초점을 둡니다.","발달 단계별 욕구를 기반으로 사회복지서비스를 개발할 수 있다":"발달 단계마다 욕구가 다르므로 이를 바탕으로 서비스를 개발할 수 있습니다.","배우자 사망 등을 겪게 되면서 심리적 우울감을 경험할 수 있다":"배우자의 죽음 등을 겪으며 노년기에는 우울감을 경험할 수 있습니다.","부모로부터 심리적, 경제적으로 독립하여 자율성을 성취하는 시기이다":"청년기는 부모에게서 심리적, 경제적으로 독립해 자율성을 이루는 시기입니다.","부모보다 또래집단의 영향력이 커진다":"청소년기에는 부모보다 또래집단의 영향력이 커집니다.","부모와 교사와의 관계, 형제관계 등을 말한다":"미시체계에는 부모와 교사의 관계, 형제관계처럼 개인과 직접 맺는 관계가 속합니다.","분화와 통합의 과정을 반복하며 이루어진다":"발달은 분화와 통합이 되풀이되면서 이루어지는 과정입니다.","비교적 안정적으로 균형 상태를 유지하기 위한 체계의 경향을 말한다":"항상성은 체계가 비교적 안정된 균형 상태를 유지하려는 경향입니다.","사회복지실천을 위한 사정도구로서 유용성을 가진다":"생태체계관점은 사회복지실천에서 사정을 위한 도구로 쓸모가 있습니다.","사회복지실천의 주요 대상이다":"가족은 사회복지실천이 주로 개입하는 대상입니다.","사회질서의 유지를 위해 법과 규칙은 준수되어야 하지만, 민주적인 절차를 통해 바뀔 수 있다고 생각한다":"후인습적 수준에서는 법과 규칙이 사회질서를 위해 지켜져야 하지만 민주적 절차로 바뀔 수 있다고 봅니다.","상상과 현실을 구분하지 못하는 사고 특징을 가진다":"유아기는 상상과 현실을 구분하지 못하는 사고 특징이 있습니다.","상상적 관중을 의식하여 작은 실수에 대해서도 번민한다":"상상적 관중은 남들이 자기를 지켜본다고 믿는 생각이며 작은 실수에도 번민하게 합니다.","생산성 대 침체성의 시기라고 하였다":"에릭슨은 중년기를 생산성 대 침체성의 시기라고 불렀습니다.","생애주기별 실천개입의 기반을 제공하였다":"에릭슨의 이론은 생애주기에 맞춘 실천개입의 기반이 되었습니다.","선천적으로 타고 나는 것이다":"우월에 대한 추구는 사람이 선천적으로 타고나는 욕구입니다.","성역할의 내면화가 이루어진다":"유아기에는 성역할이 내면화됩니다.","성인 초기의 생애 구조에 대한 평가, 중년기에 대한 가능성 탐구, 새로운 생애 구조 설계를 위한 선택 등을 과업으로 제시하였다":"레빈슨은 중년기의 과업으로 초기 생애 구조 평가, 가능성 탐구, 새 생애 구조 설계를 위한 선택을 제시했습니다.","수분과 피하지방이 감소되어 얇아지고 건조해지며 탄력성도 떨어질 수 있다":"노년기 피부는 수분과 피하지방이 줄어 얇고 건조해지며 탄력이 떨어집니다.","신체적 발달이 활발하여 제2의 성장 급등기로 불린다":"신체 발달이 활발해서 제2의 성장 급등기라고 부릅니다.","신체적 측면에서 제2의 급성장기이다":"청소년기는 신체가 급격히 자라는 제2의 급성장기입니다.","실수행위를 통해 무의식이 작용하는 증거를 파악하였다":"프로이트는 말실수 같은 실수행위에서 무의식이 작용하는 증거를 찾았습니다.","심리성적발달단계에서 생식기에 해당한다":"프로이트의 심리성적발달단계에서 청소년기는 생식기에 해당합니다.","심리적 이유기의 특징을 보인다":"청소년기는 부모에게서 심리적으로 벗어나려는 심리적 이유기의 특징을 보입니다.","아무 관계가 없는 사건들을 연결지어 생각한다":"유아기에는 서로 관계없는 사건들을 이어서 생각하기도 합니다.","어려움에 부딪힐 때 효과적으로 대처하는데 도움이 된다":"가상적 목표는 어려움에 부딪혔을 때 효과적으로 대처하도록 도와줍니다.","언어를 사회적 상호작용의 도구로 활발하게 사용하기 시작한다":"유아기에는 언어를 사회적 상호작용의 도구로 활발하게 쓰기 시작합니다.","에릭슨(E. Erikson)의 주도성 대 죄책감 단계에 해당된다":"유아기는 에릭슨의 주도성 대 죄책감 단계에 해당합니다.","영아기(0-2세)보다 발달속도가 느려진다":"유아기는 영아기보다 발달속도가 느려집니다.","예시로 음식, 돈, 칭찬 등을 들 수 있다":"정적 강화물의 예로 음식, 돈, 칭찬이 있습니다.","오래 사용하여 친근한 물건에 대한 애착심이 증가할 수 있다":"노년기에는 오래 써서 낯익은 물건에 대한 애착이 커질 수 있습니다.","외부세계에 쏟았던 에너지를 자신의 내부에 초점을 두며 개성화의 과정을 경험한다":"융은 중년기에 에너지를 자기 내부로 돌려 개성화 과정을 겪는다고 보았습니다.","음식, 물, 따뜻함 등과 같은 무조건 자극으로서 학습이 필요하지 않은 것을 말한다":"일차적 강화물은 음식, 물, 따뜻함처럼 배우지 않아도 반응하게 하는 무조건 자극입니다.","이상행동은 클라이언트가 겪는 문제의 원인이 될 수 있다":"이상행동이 있으면 그 자체가 클라이언트가 겪는 문제의 원인이 될 수 있습니다.","인간은 사회적 관심에 의해 동기화된다":"아들러는 인간이 사회적 관심에 의해 움직인다고 보았습니다.","인간은 자신의 일부로 받아들이기를 꺼리는 그림자를 가지고 있다":"그림자는 인간이 자기 일부로 받아들이기를 꺼리는 어두운 면입니다.","인간의 본성은 본래 선하다고 주장하였다":"인본주의는 인간의 본성이 본래 선하다고 봅니다.","인간의 삶과 의식 속에 내재되어 개인의 행동에 영향을 미친다":"문화는 사람의 삶과 의식 속에 스며 있어 개인의 행동에 영향을 줍니다.","인간의 욕구를 파악할 수 있는 근거를 마련하였다":"매슬로우는 인간의 욕구가 무엇인지 파악할 근거를 마련했습니다.","인간의 적응과 부적응을 판단하는 기준을 제공한다":"인간행동 지식은 사람의 적응과 부적응을 판단하는 기준을 제공합니다.","인간집단의 생활양식의 총체로 정의할 수 있다":"문화는 인간 집단이 살아가는 생활양식 전체를 가리킵니다.","인간행동은 내적 충동보다는 외적 자극에 반응하여 나타난다":"행동주의는 사람의 행동이 내적 충동보다 외부 자극에 반응해 나타난다고 봅니다.","인간행동은 예측 가능하며 통제할 수 있다":"행동주의는 인간행동을 예측할 수 있고 통제할 수 있다고 봅니다.","인간행동의 무의식적 측면을 심층적으로 분석할 수 있는 기반을 제공하였다":"프로이트는 인간행동에 숨은 무의식을 깊이 분석할 기반을 마련했습니다.","자기 부양 능력을 갖추어야 하는 시기이다":"청년기는 스스로 먹고살 수 있는 자기 부양 능력을 갖추어야 하는 시기입니다.","자신의 감정이나 경험이 매우 특별하다고 생각한다":"청소년은 자기 감정이나 경험이 매우 특별하다고 여깁니다.","자신이 타인으로부터 집중적인 관심의 대상이 된다고 믿는다":"청소년은 자기가 타인에게서 집중적인 관심을 받는다고 믿습니다.","정서의 변화가 심하며 극단적 정서를 경험하기도 한다":"청소년기에는 정서 변화가 심해 극단적인 정서를 겪기도 합니다.","정해진 시간 간격이 지난 후 강화를 주는 것이다":"고정간격계획은 정해진 시간이 지난 뒤에 강화를 주는 방식입니다.","주류와 비주류 문화 사이의 권력 차이로 차별이 발생할 수 있다":"주류 문화와 비주류 문화 사이에 권력 차이가 있으면 차별이 생길 수 있습니다.","죽음과 상실에 대한 심리적 5단계를 제시하였다":"퀴블러 로스는 죽음과 상실을 맞는 사람의 심리를 5단계로 나누어 제시했습니다.","중년기 이후의 발달을 이해하는데 도움을 제공하였다":"융의 이론은 중년기 이후의 발달을 이해하는 데 도움이 되었습니다.","직업 준비와 직업선택에 대한 의사결정을 하는 시기이다":"청년기는 직업을 준비하고 선택에 대한 의사결정을 하는 시기입니다.","집단무의식의 주요 구성요소이다":"원형은 집단무의식을 이루는 중요한 구성요소입니다.","집단의 구성 동기에 따라 자연집단과 형성집단으로 분류된다":"집단은 구성하게 된 동기에 따라 자연집단과 형성집단으로 나뉩니다.","체계가 목적 달성이 어려운 방식으로 움직이고 있다는 정보를 제공하여 체계의 변화를 도모한다":"부적 환류는 체계가 목적 달성이 어려운 방식으로 움직인다는 정보를 주어 변화를 이끕니다.","체계를 외부 환경과 구분 짓는 둘레를 말한다":"경계는 체계를 외부 환경과 구분 짓는 둘레입니다.","체계를 유지하고, 발전을 도모하고, 생존하는 것을 의미한다":"넥엔트로피는 체계가 유지되고 발전하며 살아남는 방향의 힘을 가리킵니다.","추상적 이론과 관념적 사상에 빠져 때로 부정적 정서를 경험한다":"추상적 이론이나 관념적 사상에 빠져 때때로 부정적 정서를 경험하는 것이 이 시기의 모습입니다.","코카인, 헤로인의 약물 등에 의존: 태아가 약물에 중독된 채로 태어날 수 있다":"임신부가 코카인이나 헤로인에 의존하면 태아가 약물에 중독된 채 태어날 수 있습니다.","클라이언트 사정을 위한 유용한 지식이다":"인간행동에 대한 지식은 클라이언트를 사정할 때 유용하게 쓰입니다.","클라이언트의 발달과업을 성취할 수 있도록 지원하는 근거가 된다":"발달과업에 대한 지식은 클라이언트가 과업을 성취하도록 돕는 근거가 됩니다.","타인과의 관계에서 친밀감을 형성하면서 결혼과 부모됨을 고려하는 시기이다":"청년기에는 타인과 친밀감을 형성하며 결혼과 부모가 되는 일을 생각합니다.","태아가 사망하거나 출생 시 조산, 저체중, 뇌손상 등이 발생 할 수 있다":"임신부가 방사선에 노출되면 태아가 사망하거나 조산, 저체중, 뇌손상이 생길 수 있습니다.","태아의 미숙아 출생률을 증가시킨다":"임신부의 흡연은 미숙아로 태어나는 비율을 높입니다.","특질은 자아이상(ego ideal)과 양심(conscience)으로 구성된다":"초자아의 특질은 자아이상과 양심으로 이루어집니다.","특징적 발달 중 하나로 성적 성숙이 있다":"청소년기의 특징적인 발달 중 하나는 성적 성숙입니다.","학습되고 전승되는 특징이 있다":"문화는 배워서 익히고 다음 세대로 전해지는 특징이 있습니다.","해독 기능이 없는 태아에게 축적되어 안면기형 등의 부작용을 초래 할 수 있다":"태아는 해독 기능이 없어 임신부가 마신 알코올이 쌓이고 안면기형 같은 부작용이 생길 수 있습니다.","혐오적인 사건을 표현하거나 긍정적인 강화물을 제거하는 것으로, 특정행동의 빈도를 감소시키는 결과를 초래한다":"벌은 혐오적인 사건을 주거나 긍정적 강화물을 없애서 특정 행동의 빈도를 줄입니다.","환경의 체계 수준별 개입 근거를 제시한다":"생태체계관점은 환경의 체계 수준별로 어디에 개입할지 근거를 줍니다.","후천적 학습에 의해 획득되는 특성이 있다":"문화는 태어난 뒤 배움으로 얻어지는 후천적 특성이 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
